function tokenBucket(capacity, refillPerSec, elapsedSec, start){
  start=start||0;
  var added=elapsedSec*refillPerSec;
  return Math.max(0, Math.min(capacity, start+added));
}
function leakyBucket(capacity, leakPerSec, elapsedSec, start){
  start=start||0;
  var leaked=elapsedSec*leakPerSec;
  return Math.max(0, Math.min(capacity, start-leaked));
}
function slidingWindow(max, windowSec, nowSec, hits){
  var cnt=0; for(var i=0;i<hits.length;i++){ var d=nowSec-hits[i]; if(d>=0 && d<=windowSec) cnt++; }
  return {count:cnt, allowed:cnt<max, remaining:Math.max(0,max-cnt)};
}
if (typeof module !== 'undefined' && module.exports) { module.exports = { tokenBucket:tokenBucket, leakyBucket:leakyBucket, slidingWindow:slidingWindow }; }
if (typeof window !== 'undefined') { window.RateLimitForgePure = { tokenBucket:tokenBucket, leakyBucket:leakyBucket, slidingWindow:slidingWindow }; }
